def forward(params, x, d=2):
    E2=params['E2']; P2=params['P2']; M0=params['M0']; VO0=params['VO0']; M1=params['M1']; VO1=params['VO1']; WU=params['WU']
    h=E2[x]+P2[None]
    for M,VO in [(M0,VO0),(M1,VO1)]:
        sc=h@M@h.transpose(0,2,1); sc=sc-sc.max(-1,keepdims=True)
        p=np.exp(sc); p/=p.sum(-1,keepdims=True)
        h=h+np.einsum('bij,bjk,kl->bil',p,h,VO)
    return h[:,3]@WU
def pack(p):
    return np.concatenate([p[k].ravel() for k in ['E2','P2','M0','VO0','M1','VO1','WU']])
