import re
def fstats(s):
    floats=re.findall(r'-?\d+\.\d+',s)
    digits=sum(len(n.replace('-','').replace('.','')) for n in floats)
    chars=sum(len(n) for n in floats)
    ints=[n for n in re.findall(r'-?\d+',s)]
    return len(floats),digits,chars,len(ints),len(s)
